class Decoder:
    def __init__(self):
        self.training_phrases = [
            "if x then y else x",
            "if x then if y then x else y",
            "if x then if y then if z then x else y",
            "if x then if y then if z then if w then x else y",
            "if x then if y then if z then if w then if e then x else y"
        ]

    def decode_line(self, original_line) -> str:
        """Decode a line of original text."""
        # Build a sentence tree from phrases
        sentence_tree = " ".join(
            phrase
            for phrase in self.training_phrases
            if any(phrase in original_line.lower())
        )

        # Parse sentence tree to get tokens
        tokens = sentence_tree.split()

        # Tag each token with its phrase (if any)
        tagged_tokens = [
            {
                "text": token,
                "phrase": self._get_phrase(token, sentence_tree),
                "tag": "phr" if self._is_phrase(token, original_line) else "token"
            }
            for token in tokens
        ]

        # Merge phrases into the final parsed structure
        phrase_lines = []
        for sentence in tagged_tokens:
            if "phr" in sentence:
                phrase_lines.append(sentence["text"])
            elif "token" in sentence:
                remaining = sentence["text"].split()
                for remaining_token in remaining:
                    if self._is_phrase(remaining_token, original_line):
                        phrase_lines.append(remaining_token)
                    else:
                        phrase_lines.append(remaining_token)

        # Rejoin back into a sentence
        return " ".join(phrase_lines)

    def _get_phrase(self, token, sentence):
        """Find the phrase corresponding to a token in the sentence."""
        return next((p for p in sentence if p["text"] == token), None)

    def _is_phrase(self, token, original_line):
        """Check if a token is a phrase vs. a regular token."""
        if isinstance(token, str):
            return token.strip().lower() in original_line.lower()
        return False

